/// <summary>
/// to change the item site level field called Item status to 'Active', 'Discontinued', or 'Deleted'.
/// MPJ_22974_BMSProductMDRItemStatusAndPackChange
/// </summary>
class METChangeItemStatusService
{
    InventParameters InventParameters = InventParameters::find();
    ItemId mainItemId;
    InventSiteId mainSiteId;
    Query itemFilterQuery;

    Set  itemSet;
    Set  tempItemForPackChangeSet;
    int  errorCount;         
    boolean applyMessageCap;
    #define.maxDisplayCount(5)

}

Method.Source:
    /// <summary>
    /// Checks if it can continue for the item.
    /// </summary>
    /// <param name = "_itemId">Item Id.</param>
    /// <returns>True if it can; otherwise, false.</returns>
    private boolean continueForItem(ItemId _itemId)
    {            
        boolean  res;
        QueryRun queryRun;

        if (! itemSet)
        {
            itemSet = new Set(Types::String);

            itemFilterQuery.dataSourceTable(tableNum(InventTable)).addSelectionField(fieldNum(InventTable, ItemId));
            queryRun = new QueryRun(itemFilterQuery);
            while (queryRun.next())
            {
                InventTable inventTable = queryRun.get(tableNum(InventTable));
                itemSet.add(inventTable.ItemId);
            }
        }

        res = itemSet.in(_itemId);
        
        return res;

        /* use saved values
        QueryBuildDataSource qbds;
        QueryRun queryRun;

        qbds = itemFilterQuery.dataSourceTable(tableNum(InventTable));

        if (qbds)
        {
            SysQuery::findOrCreateRange(qbds, fieldNum(InventTable, ItemId)).value(queryValue(_itemId));
        }

        queryRun = new QueryRun(itemFilterQuery);

        return queryRun.next();
        */
    }

private boolean logValidationFailure(str _message)
{
    if (!applyMessageCap || errorCount < #maxDisplayCount)
    {
        return checkFailed(_message);
    }
    return false;
}

    public static void changeStatusRunAs(container _parm)
    {
        METChangeItemStatusService itemStatusSvc = new METChangeItemStatusService();
        METChangeItemStatusContract contract = new METChangeItemStatusContract();
        InventSiteId inventSiteId;
        ItemId itemId; 
        METItemStatus itemStatus;
        str packedQuery;
        [inventSiteId, itemId, itemStatus, packedQuery] = _parm;

        contract.parmInventSiteId(inventSiteId);
        contract.parmItemId(itemId);
        contract.parmMETItemStatus(itemStatus);
        contract.parmQuery(packedQuery);

        itemStatusSvc.changeStatusInternal(contract);
    }

    protected void changeStatusInternal(METChangeItemStatusContract _metChangeItemStatusContract)
    {
        #OCCRetryCount
        Query                   query;
        QueryBuildDataSource    qbds, qbdsInventDim, qbdsInventTable, qbdsEcoResProduct;
        QueryBuildRange         qbrItem, qbrSiteId, qbrItemStatus, qbrDiscontinueDate, qbrProductType;
        
        try
        {
            query   = new Query();
            ItemId  itemId  = _metChangeItemStatusContract.parmItemId();
            InventSiteId siteId  = _metChangeItemStatusContract.parmInventSiteId();
            itemFilterQuery = _metChangeItemStatusContract.getQuery();
            errorCount = 0;

            boolean hasItemFilter = _metChangeItemStatusContract.parmItemId() != '';

            if (!hasItemFilter)
            {
                QueryBuildDataSource inventTableDS = itemFilterQuery.dataSourceTable(tableNum(InventTable));
                if (inventTableDS)
                {
                    for (int i = 1; i <= inventTableDS.rangeCount(); i++)
                    {
                        QueryBuildRange qbr = inventTableDS.range(i);
                        if (qbr.field() == fieldNum(InventTable, ItemId)
                            && qbr.value() != ''
                            && qbr.value() != '*')
                        {
                            hasItemFilter = true;
                            break;
                        }
                    }
                }
            }

            applyMessageCap = !hasItemFilter;

            qbds = query.addDataSource(tableNum(METInventItemOrderSetup));

            if (itemId != '')
            {
                qbrItem = qbds.addRange(fieldNum(METInventItemOrderSetup, ItemId));
                qbrItem.value(queryValue(itemId));
            }

            if (siteId != '')
            {
                qbdsInventDim = qbds.addDataSource(tablenum(InventDim));
                qbdsInventDim.relations(true);
                qbdsInventDim.joinMode(JoinMode::ExistsJoin);
                qbrSiteId = qbdsInventDim.addRange(fieldNum(InventDim, InventSiteId));
                qbrSiteId.value(queryValue(siteId));
            }
            if (_metChangeItemStatusContract.parmMETItemStatus() == METItemStatusTable::findByStatus(METItemsStatus::Active).ItemStatus)
            {
                qbrItemStatus = qbds.addRange(fieldNum(METInventItemOrderSetup, ItemStatus));
                qbrItemStatus.value(strFmt('((%1 == "%2") || (%1 == ""))', fieldstr(METInventItemOrderSetup, ItemStatus),
                    METItemStatusTable::findByStatus(METItemsStatus::New).ItemStatus));
            }

            QueryRun                queryRun = new QueryRun(query);

            if (_metChangeItemStatusContract.parmMETItemStatus() == METConstants::Active)
            {
                this.changeStatusToActive(queryRun);
            }
            else if (_metChangeItemStatusContract.parmMETItemStatus() == METConstants::NewStr)
            {
                this.changeStatusToNew(queryRun);
            }
            else if (_metChangeItemStatusContract.parmMETItemStatus() == METConstants::Discontinued)
            {
                this.changeStatusToDiscontinued(queryRun, _metChangeItemStatusContract);
            }
            else if (_metChangeItemStatusContract.parmMETItemStatus() == METConstants::Deleted)
            {
                this.changeStatusToDeleted(queryRun);
            }
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch
        {
            throw error("@MET:UnhandledError");
        }
        
    }

    private void incrementErrorCount()
    {
        if (!applyMessageCap)
        {
            return;
        }

        errorCount++;

        if (errorCount == #maxDisplayCount)
        {
            warning("@MET:MoreValidationMessages");
        }
    }

    /// <summary>
    /// to change the item site level field called Item status to 'Active', 'Discontinued', or 'Deleted'.
    /// MPJ_22974_BMSProductMDRItemStatusAndPackChange
    /// </summary>
    /// <param name = "_metChangeItemStatusContract">data contract </param>
    public void changeStatus(METChangeItemStatusContract _metChangeItemStatusContract)
    {
        UserId runAsUserId = InventParameters::find().METItemStatusJobRunAsUser;

        if(runAsUserId == '')
        {
            throw Error('@MET:ItemStatusJobRunAsUserMissing');
        }

        runAs(runAsUserId, 
                classNum(METChangeItemStatusService), 
                staticMethodStr(METChangeItemStatusService,changeStatusRunAs), 
                [_metChangeItemStatusContract.parmInventSiteId(), 
                    _metChangeItemStatusContract.parmItemId(), 
                    _metChangeItemStatusContract.parmMETItemStatus(), 
                    _metChangeItemStatusContract.parmQuery()]);
    }

    /// <summary>
    /// Processes METInventItemOrderSetup records (item-site combinations) that are Discontinued
    /// and past their DiscontinueDate, and attempts to transition their status to 'Deleted'.
    ///
    /// For each qualifying item-site, it examines the item's planned order sourcing rows
    /// (Purchase and Transfer orders via METReqItemTableInventDimView) and:
    ///   - Skips items that are temp-for-pack-change or child substitution items.
    ///   - Validates on-hand stock, open orders, and slot locations before deleting.
    ///   - Handles NDC (National Distribution Centre) warehouses by validating all NDC sites together.
    ///   - Cascades the delete to transfer destination sites where applicable.
    ///   - Handles intercompany sourced purchase orders by checking the source site in the other legal entity.
    /// </summary>
    /// <param name = "_queryRun">QueryRun over METInventItemOrderSetup, built in changeStatus()</param>
    private void changeStatusToDeleted(QueryRun _queryRun)
    {
        // Local variables
        InventLocation  inventLocationNDC;
        date            currentDate             = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
        Map             ndcWarehouseMap         = new Map(Types::String, Types::String);  // key: InventLocationId  |  value: InventSiteId
        Map             sourceSiteOkIntComCache = new Map(Types::String, Types::Integer); // key: ItemId + '_' + SiteId + '_' + VendIntercompanyWarehouse
        MapEnumerator   ndcWarehouseMapEnumerator;
        str             itemSiteKey;
        boolean         isTempForPackChange;
        boolean         isChild;

        // Pre-load all NDC warehouses into a map (InventLocationId -> InventSiteId).
        while select InventSiteId, InventLocationId
            from inventLocationNDC
            where inventLocationNDC.METNDCWarehouse == NoYes::Yes
        {
            ndcWarehouseMap.insert(inventLocationNDC.InventLocationId, inventLocationNDC.InventSiteId);
        }

        // Narrow the incoming QueryRun to only item-site records eligible for deletion.
        // Eligible = ItemStatus is Discontinued AND DiscontinueDate has already passed today.
        // Also applies the user's item filter from the batch dialog as an EXISTS join on InventTable,  
        // so only items matching the user's selection criteria are processed.
        QueryBuildDataSource qbdsMIIOS = _queryRun.query().dataSourceTable(tableNum(METInventItemOrderSetup));
        qbdsMIIOS.addRange(fieldNum(METInventItemOrderSetup, ItemStatus)).value(queryValue(METConstants::Discontinued));
        qbdsMIIOS.addRange(fieldNum(METInventItemOrderSetup, DiscontinueDate)).value(SysQuery::range(dateNull(), currentDate));

        QueryBuildDataSource qbdsInventTable = qbdsMIIOS.addDataSource(tableNum(InventTable));
        qbdsInventTable.joinMode(JoinMode::ExistsJoin);
        qbdsInventTable.fetchMode(QueryFetchMode::One2One);
        qbdsInventTable.addLink(fieldNum(METInventItemOrderSetup, ItemId), fieldNum(InventTable, ItemId));

        // Copy any user-defined item filter ranges onto the join.
        QueryBuildDataSource qbdsItemFilter = itemFilterQuery.dataSourceTable(tableNum(InventTable));
        for (int i = 1; i <= qbdsItemFilter.rangeCount(); i++)
        {
            QueryBuildRange qbrSource = qbdsItemFilter.range(i);
            qbdsInventTable.addRange(qbrSource.field()).value(qbrSource.value());
        }

        // Join METReqItemTableInventDimView to METInventItemOrderSetup on ItemId and SiteId,
        // filtered to Purch and Transfer planned order types only.
        // This eliminates the inner while select that was previously nested inside the main loop.
        QueryBuildDataSource qbdsView = qbdsMIIOS.addDataSource(tableNum(METReqItemTableInventDimView));
        qbdsView.joinMode(JoinMode::InnerJoin);
        qbdsView.fetchMode(QueryFetchMode::One2One);
        qbdsView.addLink(fieldNum(METInventItemOrderSetup, ItemId), fieldNum(METReqItemTableInventDimView, ItemId));
        qbdsView.addLink(fieldNum(METInventItemOrderSetup, SiteId), fieldNum(METReqItemTableInventDimView, InventSiteId));
        qbdsView.addRange(fieldNum(METReqItemTableInventDimView, ReqPOType)).value(
            strFmt('((%1.%2 == %3) || (%1.%2 == %4))',
                qbdsView.name(),
                fieldStr(METReqItemTableInventDimView, ReqPOType),
                any2int(ReqPOType::Purch),
                any2int(ReqPOType::Transfer)));

        // Outer join InventLocation on the view to resolve NDC warehouse flag and site per planned order row.
        // Outer join ensures rows with no matching warehouse are still returned (METNDCWarehouse defaults to false).
        QueryBuildDataSource qbdsLocOuter = qbdsView.addDataSource(tableNum(InventLocation));
        qbdsLocOuter.joinMode(JoinMode::OuterJoin);
        qbdsLocOuter.addLink(fieldNum(METReqItemTableInventDimView, InventLocationId), fieldNum(InventLocation, InventLocationId));

        // Pre-load temp-for-pack-change item references into a Set.
        // Collects all ItemIds that are referenced as TempItemPackChg on any METInventItemOrderSetup record.
        // Scoped to the user's item filter to avoid loading the entire table unnecessarily.
        // Used together with checkIfItemIsTemp() to identify and skip temp pack-change items.
        Set tempItemPackChgRefSet = new Set(Types::String);
        Query                tempPackChangeQuery    = new Query();
        QueryBuildDataSource inventItemOrderSetupDS = tempPackChangeQuery.addDataSource(tableNum(METInventItemOrderSetup));
        inventItemOrderSetupDS.addRange(fieldNum(METInventItemOrderSetup, TempItemPackChg)).value(SysQuery::valueNotEmptyString());

        QueryBuildDataSource inventItemOrderSetupFilter = inventItemOrderSetupDS.addDataSource(tableNum(InventTable));
        inventItemOrderSetupFilter.joinMode(JoinMode::ExistsJoin);
        inventItemOrderSetupFilter.addLink(fieldNum(METInventItemOrderSetup, TempItemPackChg), fieldNum(InventTable, ItemId));

        for (int i = 1; i <= qbdsItemFilter.rangeCount(); i++)
        {
            QueryBuildRange qbrSource = qbdsItemFilter.range(i);
            inventItemOrderSetupFilter.addRange(qbrSource.field()).value(qbrSource.value());
        }

        QueryRun tempPackChangeQueryRun = new QueryRun(tempPackChangeQuery);
        while (tempPackChangeQueryRun.next())
        {
            METInventItemOrderSetup setupRef = tempPackChangeQueryRun.get(tableNum(METInventItemOrderSetup));
            tempItemPackChgRefSet.add(setupRef.TempItemPackChg);
        }
        
        // Pre-load child item-site combinations into a Set (key: ItemId + '_' + SiteId).
        // Child items (linked via METSalesItemSubstitutionParentChild) must be skipped during deletion
        // because their status is driven by the parent item's deletion process, not independently.
        // Scoped to the user's item filter to avoid loading the entire substitution table.
        Set childItemSiteSet = new Set(Types::String);
        Query                qChild    = new Query();
        QueryBuildDataSource qbdsChild = qChild.addDataSource(tableNum(METSalesItemSubstitutionParentChild));

        QueryBuildDataSource qbdsChildFilter = qbdsChild.addDataSource(tableNum(InventTable));
        qbdsChildFilter.joinMode(JoinMode::ExistsJoin);
        qbdsChildFilter.addLink(fieldNum(METSalesItemSubstitutionParentChild, ChildItemID), fieldNum(InventTable, ItemId));

        for (int i = 1; i <= qbdsItemFilter.rangeCount(); i++)
        {
            QueryBuildRange qbrSource = qbdsItemFilter.range(i);
            qbdsChildFilter.addRange(qbrSource.field()).value(qbrSource.value());
        }

        QueryRun qrChild = new QueryRun(qChild);
        while (qrChild.next())
        {
            METSalesItemSubstitutionParentChild childRef = qrChild.get(tableNum(METSalesItemSubstitutionParentChild));
            childItemSiteSet.add(childRef.ChildItemID + '_' + childRef.InventSiteId);
        }

        // Pre-load all (ItemId, DestSiteId) pairs that have a valid non-discontinued source site.
        // Replaces the per-item-site lazy cache used in the Transfer branch — one bulk join instead of N DB calls.
        // Key format: ItemId + '_' + DestSiteId (matches itemSiteKey used in the Transfer branch).
        // Logic mirrors checkIfSourceSiteWithItemStatusNotDiscontinued: for each non-discontinued source MIIOS,
        // follow ReqItemTable -> InventDim to find the destination site that it services, confirming the
        // source warehouse belongs to the source site via InventLocation.
        Set sourceSiteOkSet = new Set(Types::String);
        METInventItemOrderSetup miiosSource;
        InventLocation          locSource;
        ReqItemTable            reqSource;
        InventDim               dimSource;

        while select ItemId from miiosSource
            where miiosSource.ItemStatus != METConstants::Discontinued
            join CovInventDimId, InventLocationIdReqMain from reqSource
                where reqSource.ItemId == miiosSource.ItemId
            join InventSiteId from dimSource
                where dimSource.inventDimId == reqSource.CovInventDimId
            exists join locSource
                where locSource.InventLocationId == reqSource.InventLocationIdReqMain
                    && locSource.InventSiteId     == miiosSource.SiteId
        {
            sourceSiteOkSet.add(miiosSource.ItemId + '_' + dimSource.InventSiteId);
        }

        // Main processing loop.
        // Each row represents one planned order sourcing row (Purchase or Transfer) for a qualifying item-site.
        // METInventItemOrderSetup, METReqItemTableInventDimView, and InventLocation are all fetched via
        // _queryRun.get() since they are joined in the single combined query built above.
        // The same METInventItemOrderSetup record may appear multiple times — once per planned order row.
        // Per-item-site flags (isTempForPackChange, isChild) are recomputed via Set lookups.
        // sourceSiteOk is resolved inline in the Transfer branch via sourceSiteOkSet.
        while (_queryRun.next())
        {
            METInventItemOrderSetup      metInventItemOrderSetup      = _queryRun.get(tableNum(METInventItemOrderSetup));
            METReqItemTableInventDimView metReqItemTableInventDimView = _queryRun.get(tableNum(METReqItemTableInventDimView));
            InventLocation               inventLocation               = _queryRun.get(tableNum(InventLocation));

            // Store current item-site on the class so nested methods (ValidateAndDelete, etc.) can reference it.
            mainItemId  = metInventItemOrderSetup.ItemId;
            mainSiteId  = metInventItemOrderSetup.SiteId;
            itemSiteKey = metInventItemOrderSetup.ItemId + '_' + metInventItemOrderSetup.SiteId;

            // Determine per row whether the item is a temp-for-pack-change item.
            // Temp items are managed as part of their associated parent item's deletion — skip them here.
            isTempForPackChange = this.checkIfItemIsTemp(metInventItemOrderSetup.ItemId)
                               && tempItemPackChgRefSet.in(metInventItemOrderSetup.ItemId);

            // Determine per row whether the item-site is a child substitution item.
            // Child items are driven by parent deletion logic — skip them here.
            isChild = childItemSiteSet.in(itemSiteKey);

            if (metReqItemTableInventDimView.ReqPOType == ReqPOType::Purch)
            {
                if (metReqItemTableInventDimView.METInterCompanySourced == NoYes::Yes)
                {
                    // Purch - Intercompany sourced
                    // The item is sourced from another legal entity via an intercompany PO.
                    // Validate that the intercompany source site (in the other legal entity) is not
                    // discontinued before we proceed with deletion on the current site.
                    // Cached per item-site-warehouse combination to avoid repeated cross-company DB calls.
                    boolean isSourceSiteOkIntCom;
                    str     rowSourceSiteOkIntComCacheKey = metInventItemOrderSetup.ItemId + '_' + metInventItemOrderSetup.SiteId + '_' + metReqItemTableInventDimView.VendIntercompanyWarehouse;

                    if (sourceSiteOkIntComCache.exists(rowSourceSiteOkIntComCacheKey))
                    {
                        isSourceSiteOkIntCom = sourceSiteOkIntComCache.lookup(rowSourceSiteOkIntComCacheKey);
                    }
                    else
                    {
                        isSourceSiteOkIntCom = this.checkIfSourceSiteWithItemStatusNotDiscontinued_IntCom(metInventItemOrderSetup, metReqItemTableInventDimView);
                        sourceSiteOkIntComCache.insert(rowSourceSiteOkIntComCacheKey, isSourceSiteOkIntCom);
                    }

                    // Skip if the outer item is a temp/child item, or if the intercompany source site is not ready.
                    if (isTempForPackChange
                        || isChild
                        || !isSourceSiteOkIntCom)
                    {
                        continue;
                    }

                    if (inventLocation.METNDCWarehouse)
                    {
                        // NDC warehouse: must validate all NDC warehouses as a group before deleting any.
                        // If all pass, delete across every NDC warehouse.
                        if (this.changeStatusToDeleted_ValidateNDC(ndcWarehouseMap, metReqItemTableInventDimView, metReqItemTableInventDimView.ItemId))
                        {
                            ndcWarehouseMapEnumerator = ndcWarehouseMap.getEnumerator();
                            while (ndcWarehouseMapEnumerator.moveNext())
                            {
                                this.changeStatusToDeleted_ValidateAndDelete(
                                    ndcWarehouseMapEnumerator.currentValue(),
                                    ndcWarehouseMapEnumerator.currentKey(),
                                    metInventItemOrderSetup,
                                    metReqItemTableInventDimView,
                                    false);
                            }
                        }
                    }
                    else
                    {
                        // Non-NDC warehouse: validate and delete for this specific site/warehouse only.
                        this.changeStatusToDeleted_ValidateAndDelete(
                            inventLocation.InventSiteId,
                            inventLocation.InventLocationId,
                            metInventItemOrderSetup,
                            metReqItemTableInventDimView,
                            false);
                    }
                }
                else
                {
                    // Purch - Standard (non-intercompany)
                    // The sourcing item in the planned order may differ from the outer item
                    // (e.g. a pack-change scenario where a different item is used as source).
                    // Check the sourcing item's temp/child status and item filter independently.
                    boolean isTempForPackChangeRow;
                    boolean isChildRow;

                    isTempForPackChangeRow = this.checkIfItemIsTemp(metReqItemTableInventDimView.ItemId)
                                          && tempItemPackChgRefSet.in(metReqItemTableInventDimView.ItemId);

                    str rowSiteKey = metReqItemTableInventDimView.ItemId + '_' + metInventItemOrderSetup.SiteId;
                    isChildRow     = childItemSiteSet.in(rowSiteKey);

                    // Skip if the sourcing item is a temp/child item, or is outside the user's item filter.
                    if (isTempForPackChangeRow
                        || isChildRow
                        || !this.continueForItem(metReqItemTableInventDimView.ItemId))
                    {
                        continue;
                    }

                    if (inventLocation.METNDCWarehouse)
                    {
                        // NDC warehouse: must validate all NDC warehouses as a group before deleting any.
                        // If all pass, delete across every NDC warehouse.
                        if (this.changeStatusToDeleted_ValidateNDC(ndcWarehouseMap, metReqItemTableInventDimView, metReqItemTableInventDimView.ItemId))
                        {
                            ndcWarehouseMapEnumerator = ndcWarehouseMap.getEnumerator();
                            while (ndcWarehouseMapEnumerator.moveNext())
                            {
                                this.changeStatusToDeleted_ValidateAndDelete(
                                    ndcWarehouseMapEnumerator.currentValue(),
                                    ndcWarehouseMapEnumerator.currentKey(),
                                    metInventItemOrderSetup,
                                    metReqItemTableInventDimView,
                                    false,
                                    true);
                            }
                        }
                    }
                    else
                    {
                        // Non-NDC warehouse: validate and delete for this specific site/warehouse only.
                        this.changeStatusToDeleted_ValidateAndDelete(
                            inventLocation.InventSiteId,
                            inventLocation.InventLocationId,
                            metInventItemOrderSetup,
                            metReqItemTableInventDimView,
                            false,
                            true);
                    }
                }
            }
            else if (metReqItemTableInventDimView.ReqPOType == ReqPOType::Transfer)
            {
                // Transfer order
                // The item is replenished via a transfer from another site.
                // sourceSiteOk resolved via pre-loaded Set (O(log n), no DB call).
                // Skip if the outer item is a temp/child item, or if no valid non-discontinued source site exists.
                if (isTempForPackChange
                    || isChild
                    || !sourceSiteOkSet.in(itemSiteKey))
                {
                    continue;
                }

                if (inventLocation.METNDCWarehouse)
                {
                    // NDC warehouse: must validate all NDC warehouses as a group before deleting any.
                    // If all pass, delete across every NDC warehouse.
                    if (this.changeStatusToDeleted_ValidateNDC(ndcWarehouseMap, metReqItemTableInventDimView, metReqItemTableInventDimView.ItemId))
                    {
                        ndcWarehouseMapEnumerator = ndcWarehouseMap.getEnumerator();
                        while (ndcWarehouseMapEnumerator.moveNext())
                        {
                            this.changeStatusToDeleted_ValidateAndDelete(
                                ndcWarehouseMapEnumerator.currentValue(),
                                ndcWarehouseMapEnumerator.currentKey(),
                                metInventItemOrderSetup,
                                metReqItemTableInventDimView,
                                false,
                                true);
                        }
                    }
                }
                else
                {
                    // Non-NDC warehouse: validate and delete for this specific site/warehouse only.
                    this.changeStatusToDeleted_ValidateAndDelete(
                        inventLocation.InventSiteId,
                        inventLocation.InventLocationId,
                        metInventItemOrderSetup,
                        metReqItemTableInventDimView,
                        false,
                        true);
                }
            }
        }
    }

    /// <summary>
    /// Validate the record and status to Delete
    /// </summary>
    /// <param name = "_inventSiteId">InventSiteId of the warehouse being processed</param>
    /// <param name = "_inventLocationId">InventLocationId of the warehouse being processed</param>
    /// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup</param>
    /// <param name = "_metReqItemTableInventDimView">Planned order view row (pre-fetched by caller)</param>
    /// <param name = "_calledFromTransferSite">boolean</param>
    /// <param name = "_checkForTransferOrder">boolean</param>
    private void changeStatusToDeleted_ValidateAndDelete(InventSiteId _inventSiteId, InventLocationId _inventLocationId, METInventItemOrderSetup _metInventItemOrderSetup, METReqItemTableInventDimView _metReqItemTableInventDimView, boolean _calledFromTransferSite, boolean _checkForTransferOrder = false)
    {
        if (this.changeStatusToDeleted_Validate(_inventSiteId, _inventLocationId, _metReqItemTableInventDimView, _metInventItemOrderSetup.ItemId)) // Validate main Item
        {
            // Fetch InventDim once — shared by both updateStatusToDeletedMain calls below.
            InventDim inventDim = InventDim::find(_metInventItemOrderSetup.InventDimId);

            if (_metInventItemOrderSetup.TempItemPackChg
                && this.changeStatusToDeleted_Validate(_inventSiteId, _inventLocationId, _metReqItemTableInventDimView, _metInventItemOrderSetup.TempItemPackChg)) // If main Item contains Temp Item and validate temp Item
            {
                if (_calledFromTransferSite)
                {
                    METInventItemOrderSetup metInventItemOrderSetupTransferSite, metInventItemOrderSetupTransferSiteTempItem, metInventItemOrderSetupMainSite;

                    select firstonly metInventItemOrderSetupMainSite
                        where metInventItemOrderSetupMainSite.SiteId == mainSiteId
                        && metInventItemOrderSetupMainSite.ItemId == mainItemId;

                    select firstonly forupdate metInventItemOrderSetupTransferSite
                        where metInventItemOrderSetupTransferSite.SiteId == _metInventItemOrderSetup.SiteId
                        && metInventItemOrderSetupTransferSite.ItemId == _metInventItemOrderSetup.ItemId
                        && metInventItemOrderSetupTransferSite.ItemStatus != METConstants::Deleted
                        && metInventItemOrderSetupTransferSite.ItemStatus != METConstants::Discontinued;

                    if(metInventItemOrderSetupMainSite && metInventItemOrderSetupTransferSite)
                    {
                        this.copyDelReasonAFromSourceToTransferSiteAndDeleteMain(metInventItemOrderSetupMainSite, metInventItemOrderSetupTransferSite);
                    }

                    select firstonly forupdate metInventItemOrderSetupTransferSiteTempItem
                        where metInventItemOrderSetupTransferSiteTempItem.SiteId == metInventItemOrderSetupTransferSite.SiteId
                        && metInventItemOrderSetupTransferSiteTempItem.ItemId == metInventItemOrderSetupTransferSite.TempItemPackChg
                        && metInventItemOrderSetupTransferSiteTempItem.ItemStatus != METConstants::Deleted
                        && metInventItemOrderSetupTransferSiteTempItem.ItemStatus != METConstants::Discontinued;

                    if(metInventItemOrderSetupMainSite && metInventItemOrderSetupTransferSiteTempItem)
                    {
                        this.copyDelReasonAFromSourceToTransferSiteAndDeleteMain(metInventItemOrderSetupMainSite, metInventItemOrderSetupTransferSiteTempItem);
                    }
                }
                else
                {
                    this.updateStatusToDeletedMain(_metInventItemOrderSetup.ItemId, inventDim, _metInventItemOrderSetup); // Delete status to Main item
                    this.updateStatusToDeletedMain(_metInventItemOrderSetup.TempItemPackChg, inventDim, METInventItemOrderSetup::findByItemAndSite(_metInventItemOrderSetup.TempItemPackChg, _metInventItemOrderSetup.SiteId)); // Delete status to Temp item
                }

                if (_calledFromTransferSite) // Change status to delete job for all child linked
                {
                    METChangeItemStatusHelper metChangeItemStatusHelper = new METChangeItemStatusHelper();
                    metChangeItemStatusHelper.updateItemStatusOfTransferSite(_metInventItemOrderSetup.ItemId, _metInventItemOrderSetup.SiteId, METConstants::Deleted);
                }
            }
            else if (!_metInventItemOrderSetup.TempItemPackChg
                && this.changeStatusToDeleted_Validate(_metReqItemTableInventDimView.InventSiteId, _metReqItemTableInventDimView.InventLocationId, _metReqItemTableInventDimView, _metInventItemOrderSetup.ItemId)) // If no temp item found
            {
                if (_calledFromTransferSite)
                {
                    METInventItemOrderSetup metInventItemOrderSetupMainSite;

                    select firstonly metInventItemOrderSetupMainSite
                        where metInventItemOrderSetupMainSite.SiteId == _inventSiteId
                        && metInventItemOrderSetupMainSite.ItemId == _metInventItemOrderSetup.ItemId;

                    this.copyDelReasonAndVendReplacementFromSourceToTransferSiteMain(metInventItemOrderSetupMainSite,_metInventItemOrderSetup);
                }
                this.updateStatusToDeletedMain(_metInventItemOrderSetup.ItemId, inventDim, _metInventItemOrderSetup); // Delete status to Main item

                if (_calledFromTransferSite) // Change status to delete job for all child linked
                {
                    METChangeItemStatusHelper metChangeItemStatusHelper = new METChangeItemStatusHelper();
                    metChangeItemStatusHelper.updateItemStatusOfTransferSite(_metInventItemOrderSetup.ItemId, _metInventItemOrderSetup.SiteId, METConstants::Deleted);
                }
            }

            if (_checkForTransferOrder)
            {
                this.checkAndDeleteIfItemIsTOInOtherSites(_inventSiteId, _inventLocationId, _metInventItemOrderSetup);
                this.checkAndDeleteIfItemIsTOInOtherSites_IntComp(_inventSiteId, _inventLocationId, _metInventItemOrderSetup);
            }
        }
    }

    /// <summary>
    /// Check if Transfer order is present or not
    /// </summary>
    /// <param name = "_inventLocation">InventLocation</param>
    /// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup</param>
    private void checkAndDeleteIfItemIsTOInOtherSites(InventSiteId _inventSiteId, InventLocationId _inventLocationId, METInventItemOrderSetup _metInventItemOrderSetup )
    {
        ReqItemTable reqItemTableTOInOtherSite;
        METInventItemOrderSetup metInventItemOrderSetupTransferSite, metInventItemOrderSetupTransferSiteTempItem;

        // Check if Item is a transferorder in other sites
        while select ItemId, CovInventDimId, ReqPOType, InventLocationIdReqMain, VendId, RecId
            from reqItemTableTOInOtherSite
            where reqItemTableTOInOtherSite.ItemId == _metInventItemOrderSetup.ItemId &&
            reqItemTableTOInOtherSite.InventLocationIdReqMain == _inventLocationId &&
            reqItemTableTOInOtherSite.ReqPOType == ReqPOType::Transfer
        {
            InventSite inventSite = InventSite::find(InventDim::find(reqItemTableTOInOtherSite.CovInventDimId).InventSiteId);

            select firstonly metInventItemOrderSetupTransferSite
                where metInventItemOrderSetupTransferSite.SiteId == inventSite.SiteId
                && metInventItemOrderSetupTransferSite.ItemId == _metInventItemOrderSetup.ItemId
                && metInventItemOrderSetupTransferSite.ItemStatus != METConstants::Deleted;

            if (inventSite.METNDCSite && metInventItemOrderSetupTransferSite && metInventItemOrderSetupTransferSite.ItemStatus != METConstants::Discontinued)
            {
                this.copyDelReasonAndVendReplacementFromSourceToTransferSite(_metInventItemOrderSetup, metInventItemOrderSetupTransferSite); // This will execute for both if temp item is present or not present
                METInventItemOrderSetup::updateChildItemSiteStatusToDiscontinue(metInventItemOrderSetupTransferSite.ItemId, metInventItemOrderSetupTransferSite.SiteId, metInventItemOrderSetupTransferSite);
                if (metInventItemOrderSetupTransferSite.TempItemPackChg)
                {
                    select firstonly metInventItemOrderSetupTransferSiteTempItem
                        where metInventItemOrderSetupTransferSiteTempItem.SiteId == metInventItemOrderSetupTransferSite.SiteId
                        && metInventItemOrderSetupTransferSiteTempItem.ItemId == metInventItemOrderSetupTransferSite.TempItemPackChg
                        && metInventItemOrderSetupTransferSiteTempItem.ItemStatus != METConstants::Deleted
                        && metInventItemOrderSetupTransferSiteTempItem.ItemStatus != METConstants::Discontinued;

                    if (metInventItemOrderSetupTransferSiteTempItem)
                    {
                        this.copyDelReasonAndVendReplacementFromSourceToTransferSite(metInventItemOrderSetupTransferSite, metInventItemOrderSetupTransferSiteTempItem);
                        METInventItemOrderSetup::updateChildItemSiteStatusToDiscontinue(metInventItemOrderSetupTransferSiteTempItem.ItemId, metInventItemOrderSetupTransferSiteTempItem.SiteId, metInventItemOrderSetupTransferSiteTempItem);
                    }

                }
            }
            else if (!inventSite.METNDCSite && metInventItemOrderSetupTransferSite)
            {
                InventDim       inventDimLoc = InventDim::find(reqItemTableTOInOtherSite.CovInventDimId);
                InventLocation  invnetLocationLoc;

                select firstonly METNDCWarehouse, InventSiteId, InventLocationId from invnetLocationLoc
                    where invnetLocationLoc.InventLocationId == inventDimLoc.InventLocationId
                    && invnetLocationLoc.InventSiteId == inventDimLoc.InventSiteId;
                
                if (invnetLocationLoc)
                {
                    METReqItemTableInventDimView viewLoc;
                    select firstonly viewLoc
                        where viewLoc.ReqItemTableRecId == reqItemTableTOInOtherSite.RecId;
                    this.changeStatusToDeleted_ValidateAndDelete(invnetLocationLoc.InventSiteId, invnetLocationLoc.InventLocationId, metInventItemOrderSetupTransferSite, viewLoc, true);
                }
            }
        }
       
    }

    /// <summary>
    /// Check if Transfer order is present or not for Intercompany
    /// </summary>
    /// <param name = "_inventLocation">Warehouse table</param>
    /// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup table</param>
    private void checkAndDeleteIfItemIsTOInOtherSites_IntComp(InventSiteId _inventSiteId, InventLocationId _inventLocationId, METInventItemOrderSetup _metInventItemOrderSetup )
    {
        DataAreaId currentLegalEntity = curExt();
        changecompany(inventParameters.METInterCompanyPurchaseLegalEntity)
        {
            METInventItemOrderSetup metInventItemOrderSetupTransferSite, metInventItemOrderSetupTransferSiteTempItem;
            METReqItemTableInventDimView metReqItemTableInventDimView;

            // Check if Item is a transferorder in other sites
            while select ItemId, CovInventDimId, ReqPOType, InventLocationIdReqMain, VendId, RecId, VendIntercompanyWarehouse, ReqItemTableRecId
                from metReqItemTableInventDimView
                where metReqItemTableInventDimView.ItemId == _metInventItemOrderSetup.ItemId
                && metReqItemTableInventDimView.ReqPOType == ReqPOType::Purch
                && metReqItemTableInventDimView.METInterCompanySourced == NoYes::Yes
            {
                if (this.getSiteFromCurrentLegalEntity(metReqItemTableInventDimView.VendIntercompanyWarehouse, currentLegalEntity)  == _inventSiteId && metReqItemTableInventDimView.VendIntercompanyWarehouse == _inventLocationId)
                {
                    InventSite inventSite = InventSite::find(InventDim::find(metReqItemTableInventDimView.CovInventDimId).InventSiteId);

                    select firstonly forupdate metInventItemOrderSetupTransferSite
                        where metInventItemOrderSetupTransferSite.SiteId == inventSite.SiteId
                        && metInventItemOrderSetupTransferSite.ItemId == _metInventItemOrderSetup.ItemId;

                    if (inventSite.METNDCSite && metInventItemOrderSetupTransferSite && (metInventItemOrderSetupTransferSite.ItemStatus != METConstants::Deleted && metInventItemOrderSetupTransferSite.ItemStatus != METConstants::Discontinued))
                    {
                        this.copyDelReasonAndVendReplacementFromSourceToTransferSiteMain(_metInventItemOrderSetup, metInventItemOrderSetupTransferSite);
                        if (metInventItemOrderSetupTransferSite.TempItemPackChg)
                        {
                            select firstonly forupdate metInventItemOrderSetupTransferSiteTempItem
                                where metInventItemOrderSetupTransferSiteTempItem.SiteId == metInventItemOrderSetupTransferSite.SiteId
                                && metInventItemOrderSetupTransferSiteTempItem.ItemId == metInventItemOrderSetupTransferSite.TempItemPackChg;

                            if(metInventItemOrderSetupTransferSiteTempItem.ItemStatus != METConstants::Deleted && metInventItemOrderSetupTransferSiteTempItem.ItemStatus != METConstants::Discontinued)
                            {
                                this.copyDelReasonAndVendReplacementFromSourceToTransferSiteMain(metInventItemOrderSetupTransferSite, metInventItemOrderSetupTransferSiteTempItem);
                            }

                        }
                    }
                    else if (!inventSite.METNDCSite && metInventItemOrderSetupTransferSite)
                    {
                        this.changeStatusToDeleted_ValidateAndDelete(_inventSiteId, _inventLocationId, metInventItemOrderSetupTransferSite, metReqItemTableInventDimView, true);
                    }

                }
            }
        }
    }

    private InventSiteId getSiteFromCurrentLegalEntity(InventLocationId _inventLocationId, DataAreaId _searchLegalEntity)
    {
        InventSiteId    inventSiteId;

        changecompany(_searchLegalEntity)
        {
            InventLocation inventLocation;

            select firstonly InventSiteId from inventLocation
                where inventLocation.InventLocationId == _inventLocationId;

            inventSiteId = inventLocation.InventSiteId;
        }

        return inventSiteId;
        
    }

    /// <summary>
    /// Copy reason code, vend replacement and update to discontinue
    /// </summary>
    /// <param name = "_metInventItemOrderSetupSource">METInventItemOrderSetup</param>
    /// <param name = "_metInventItemOrderSetupDestination">METInventItemOrderSetup</param>
    private void copyDelReasonAndVendReplacementFromSourceToTransferSiteMain(METInventItemOrderSetup _metInventItemOrderSetupSource, METInventItemOrderSetup _metInventItemOrderSetupDestination)
    {
        if(_metInventItemOrderSetupDestination)
        {
            this.copyDelReasonAndVendReplacementFromSourceToTransferSite(_metInventItemOrderSetupSource,_metInventItemOrderSetupDestination);

            METSalesItemSubstitutionParentChild childItems;
            METInventItemOrderSetup metInventItemOrderSetupForChildItems;
                                                        
            while select ChildItemID, InventSiteId from childItems
                join forupdate metInventItemOrderSetupForChildItems
                where childItems.ParentItemID == _metInventItemOrderSetupDestination.ItemId
                && childItems.InventSiteId == _metInventItemOrderSetupDestination.SiteId
                && metInventItemOrderSetupForChildItems.ItemId == childItems.ChildItemID
                && metInventItemOrderSetupForChildItems.SiteId == childItems.InventSiteId
            {
                this.copyDelReasonAndVendReplacementFromSourceToTransferSite(_metInventItemOrderSetupDestination,metInventItemOrderSetupForChildItems);
            }
        }
    }

    /// <summary>
    /// Copy deletion reason and Vend replacement
    /// </summary>
    /// <param name = "_metInventItemOrderSetupSource">METInventItemOrderSetup</param>
    /// <param name = "_metInventItemOrderSetupDestination">METInventItemOrderSetup</param>
    private void copyDelReasonAndVendReplacementFromSourceToTransferSite(METInventItemOrderSetup _metInventItemOrderSetupSource, METInventItemOrderSetup _metInventItemOrderSetupDestination)
    {
        InventItemPurchSetup inventItemPurchSetup = InventItemPurchSetup::find(_metInventItemOrderSetupDestination.ItemId,_metInventItemOrderSetupDestination.InventDimId);
        
        ttsbegin;

        if (_metInventItemOrderSetupDestination)
        {
            _metInventItemOrderSetupDestination.selectForUpdate(true);
            _metInventItemOrderSetupDestination.ItemStatus = METConstants::Discontinued;
            if (!_metInventItemOrderSetupDestination.DiscontinueDate)
            {
                _metInventItemOrderSetupDestination.DiscontinueDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
            }
            _metInventItemOrderSetupDestination.VendReplacement = _metInventItemOrderSetupSource.VendReplacement;
            _metInventItemOrderSetupDestination.DeletionReason = _metInventItemOrderSetupSource.DeletionReason;
            _metInventItemOrderSetupDestination.update();
        }

        if (inventItemPurchSetup)
        {
            inventItemPurchSetup.selectForUpdate(true);
            inventItemPurchSetup.Stopped = true;
            inventItemPurchSetup.update();
        }

        ttscommit;
    }

    /// <summary>
    /// Checks whether the transfer source site for the given item still has a non-discontinued record
    /// in METInventItemOrderSetup. Returns true if such a record exists (source site is not fully discontinued),
    /// which is a prerequisite before the transfer destination site can be marked as Deleted.
    ///
    /// The source site is resolved by finding the planned order (ReqItemTable) for this item at this site,
    /// then tracing back via InventLocationIdReqMain to the supplying warehouse and its site.
    /// </summary>
    /// <param name = "_metInventItemOrderSetup">The item-site record being evaluated for deletion</param>
    /// <returns>True if the source site has a non-discontinued record; false otherwise</returns>
    private boolean checkIfSourceSiteWithItemStatusNotDiscontinued(METInventItemOrderSetup _metInventItemOrderSetup)
    {
        METInventItemOrderSetup metInventItemOrderSetupSourceSite;
        ReqItemTable            reqItemTableSourceSite;
        InventLocation          inventLocation;
        InventDim               inventDimSourceSite;

        select firstonly RecId from metInventItemOrderSetupSourceSite
            exists join inventLocation
            exists join reqItemTableSourceSite
            exists join inventDimSourceSite
            where metInventItemOrderSetupSourceSite.ItemId   == _metInventItemOrderSetup.ItemId
               && metInventItemOrderSetupSourceSite.ItemStatus != METConstants::Discontinued
               && metInventItemOrderSetupSourceSite.SiteId   == inventLocation.InventSiteId
               && inventLocation.InventLocationId            == reqItemTableSourceSite.InventLocationIdReqMain
               && reqItemTableSourceSite.ItemId              == _metInventItemOrderSetup.ItemId
               && reqItemTableSourceSite.CovInventDimId      == inventDimSourceSite.inventDimId
               && inventDimSourceSite.InventSiteId           == _metInventItemOrderSetup.SiteId;

        return metInventItemOrderSetupSourceSite.RecId != 0;
    }

    /// <summary>
    /// Check if source site with item status is not discontinued
    /// </summary>
    /// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup table</param>
    /// <param name = "_vendAccount">Vendor account</param>
    /// <returns>boolean</returns>
    private boolean checkIfSourceSiteWithItemStatusNotDiscontinued_IntCom(METInventItemOrderSetup _metInventItemOrderSetup, METReqItemTableInventDimView _metReqItemTableInventDimView)
    {
        boolean ret;

        changecompany(inventParameters.METInterCompanyPurchaseLegalEntity)
        {
            METInventItemOrderSetup metInventItemOrderSetupDiscontinued;
            InventLocation          inventLocation;

            select firstonly RecId from metInventItemOrderSetupDiscontinued
                where metInventItemOrderSetupDiscontinued.ItemId    == _metInventItemOrderSetup.ItemId
                   && metInventItemOrderSetupDiscontinued.ItemStatus != METConstants::Discontinued
                exists join inventLocation
                    where inventLocation.InventLocationId == _metReqItemTableInventDimView.VendIntercompanyWarehouse
                       && inventLocation.InventSiteId     == metInventItemOrderSetupDiscontinued.SiteId;

            ret = metInventItemOrderSetupDiscontinued.RecId != 0;
        }

        return ret;
    }

    /// <summary>
    /// Validate Delete batch data
    /// </summary>
    /// <param name = "_inventSiteId">InventSiteId of the warehouse being validated</param>
    /// <param name = "_inventLocationId">InventLocationId of the warehouse being validated</param>
    /// <param name = "_metReqItemTableInventDimView">Planned order view row (pre-fetched by caller)</param>
    /// <param name = "_metReqItemTable">METReqItemTable record (pre-fetched by caller)</param>
    /// <param name = "_itemId">ItemId to validate</param>
    /// <returns>boolean</returns>
    private boolean changeStatusToDeleted_Validate(
      InventSiteId                    _inventSiteId,
      InventLocationId                _inventLocationId,
      METReqItemTableInventDimView    _metReqItemTableInventDimView,
      ItemId                          _itemId)
    {
        boolean ret         = true;

        InventWarehouseOnHandIncludingCWItemAggregatedView inventOnHandView;

        select firstonly inventOnHandView
          where inventOnHandView.ItemNumber            == _itemId
              && inventOnHandView.InventorySiteId      == _metReqItemTableInventDimView.InventSiteId
              && inventOnHandView.InventoryWarehouseId == _metReqItemTableInventDimView.InventLocationId;

        if (inventOnHandView.AvailableOnHandQuantityMapped || inventOnHandView.PdsCWAvailOnHandQuantityMapped)
        {
            ret = this.logValidationFailure(strFmt("@MET:OnHandValidation", _itemId, _metReqItemTableInventDimView.InventSiteId, _metReqItemTableInventDimView.InventLocationId));
        }

        if (inventOnHandView.OrderedQuantityMapped || 
            inventOnHandView.PdsCWOrderedQuantityMapped ||
            inventOnHandView.ReservedOnHandQuantityMapped ||
            inventOnHandView.PdsCWReservOnHandQuantityMapped || 
            inventOnHandView.ReservedOrderedQuantityMapped)
        {
            ret = this.logValidationFailure(strFmt("@MET:OpenPOTOValidation", _itemId, _metReqItemTableInventDimView.InventSiteId, _metReqItemTableInventDimView.InventLocationId)) && ret;
        }

        if (_metReqItemTableInventDimView.SlotLoc1Area)
        {
            ret = this.logValidationFailure(strFmt("@MET:SlotLocation1Validation", _itemId, _metReqItemTableInventDimView.InventSiteId, _metReqItemTableInventDimView.InventLocationId)) && ret;
        }

        if (_metReqItemTableInventDimView.SlotLoc2Area)
        {
            ret = this.logValidationFailure(strFmt("@MET:SlotLocation2Validation", _itemId, _metReqItemTableInventDimView.InventSiteId, _metReqItemTableInventDimView.InventLocationId)) && ret;
        }

        if (inventOnHandView.AvailableOnHandQuantity || 
            inventOnHandView.AvailableOrderedQuantity ||
            inventOnHandView.ReservedOnHandQuantity ||  
            inventOnHandView.ReservedOrderedQuantityMapped)
        {
            ret = this.logValidationFailure(strFmt("@MET:OpenSOITValidation", _itemId, _metReqItemTableInventDimView.InventSiteId, _metReqItemTableInventDimView.InventLocationId)) && ret;
        }

        if (!ret)
        {
            this.incrementErrorCount();
        }

        return ret;
    }

    /// <summary>
    /// To change the item site level field called Item status to 'Deleted'.
    /// </summary>
    /// <param name = "_itemId">Item Id</param>
    /// <param name = "_inventDim">Invent Dim</param>
    /// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup table</param>
    private void updateStatusToDeletedMain(ItemId    _itemId, InventDim _inventDim, METInventItemOrderSetup _metInventItemOrderSetup)
    {
        if (_itemId)
        {
            this.updateStatusToDeleted(_metInventItemOrderSetup, _inventDim.inventDimId);
                                
            METSalesItemSubstitutionParentChild childItems;
                                                            
            while select ChildItemID, InventSiteId from childItems
                    where childItems.ParentItemID == _itemId
                    && childItems.InventSiteId == _inventDim.InventSiteId
            {
                METInventItemOrderSetup metInventItemOrderSetupForChildItems;
                                    
                select firstonly metInventItemOrderSetupForChildItems
                        where metInventItemOrderSetupForChildItems.ItemId   == childItems.ChildItemID &&
                           metInventItemOrderSetupForChildItems.SiteId     == childItems.InventSiteId;

                if (metInventItemOrderSetupForChildItems)
                {
                    this.updateStatusToDeleted(metInventItemOrderSetupForChildItems, _inventDim.inventDimId);
                }
            }
        }
    }

    /// <summary>
    /// To change the item site level field called Item status to 'Deleted'.
    /// </summary>
    /// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup table</param>
    /// <param name = "_inventDimId">Invent Dim Id</param>
    private void updateStatusToDeleted( METInventItemOrderSetup     _metInventItemOrderSetup,
                                        InventDimId                 _inventDimId)
    {
        if (_metInventItemOrderSetup)
        {
            ttsbegin;

            _metInventItemOrderSetup.selectForUpdate(true);
            _metInventItemOrderSetup.ItemStatus         = METConstants::Deleted;
            _metInventItemOrderSetup.DeleteStatusDate   = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
            _metInventItemOrderSetup.SubrangeId         = '';
            _metInventItemOrderSetup.SubrangeDesc       = '';
            _metInventItemOrderSetup.update();

            InventItemPurchSetup inventItemPurchSetup       = InventItemPurchSetup::find(_metInventItemOrderSetup.ItemId, _inventDimId, true);

            if (inventItemPurchSetup)
            {
                inventItemPurchSetup.Override = true;
                inventItemPurchSetup.Stopped = true;
                inventItemPurchSetup.update();
                
            }

            ttscommit;
        }
    }

    /// <summary>
    /// To check whether open purchase line or transfer line exist.
    /// MPJ_22974_BMSProductMDRItemStatusAndPackChange
    /// </summary>
    /// <param name = "_itemId">Item </param>
    /// <returns>boolean value</returns>
    private boolean isPOQtyOrTransQtyExist(ItemId _itemId)
    {
        boolean             ret;
        PurchLine           purchLine;
        InventTransferLine  inventTransferLine;
        InventTransferTable inventTransferTable;

        select firstonly RecId from purchLine
            where purchLine.ItemId == _itemId &&
                  purchLine.PurchStatus  == PurchStatus::Backorder;
        
        select firstonly RecId from inventTransferLine
            where inventTransferLine.ItemId == _itemId
            exists join inventTransferTable
                where inventTransferTable.TransferId == inventTransferLine.TransferId &&
                inventTransferTable.TransferStatus != InventTransferStatus::Shipped;
        
        if (purchLine || inventTransferLine)
        {
            ret = true;
        }

        return ret;
    }

/// <summary>
/// To check whether physical inventory fore the item is zero
/// MPJ_22974_BMSProductMDRItemStatusAndPackChange
/// </summary>
/// <param name = "_itemId">Item </param>
/// <param name = "_siteId">site </param>
/// <returns>boolean value</returns>
private boolean isPhysicalInventoryValueZero(ItemId _itemId, InventSiteId _siteId)
{
    boolean         ret;
    InventOnhand    inventOnhand;
    InventDim       inventDim;
    InventDimParm   inventDimParm;
    
    inventDim.InventSiteId = _siteId;
    inventDim = InventDim::findOrCreate(inventDim);
    inventDimParm.initFromInventDim(inventDim);
    inventOnhand = InventOnhand::newParameters(_itemId, inventDim, inventDimParm);
    
    if (!inventOnhand.availPhysical())
    {
        ret = true;
    }
    
    return ret;
}

    /// <summary>
    /// To change the item site level field called Item status to 'Discontinued'.
    /// </summary>
    /// <param name = "_queryRun">QueryRun</param>
    /// <param name = "_metChangeItemStatusContract">METChangeItemStatusContract</param>
    private void changeStatusToDiscontinued(QueryRun _queryRun, METChangeItemStatusContract _metChangeItemStatusContract)
    {
        Set substitutionChildItemSet = this.getSubstitutionChildItemSet();
        
        while(_queryRun.next())
        {
            
            METInventItemOrderSetup metInventItemOrderSetup, metInventItemOrderSetupToActive, metInventItemOrderSetupToDiscontinue;
            InventItemPurchSetup    inventItemPurchSetup;

            metInventItemOrderSetup = _queryRun.get(tableNum(METInventItemOrderSetup));

            if (this.continueForItem(metInventItemOrderSetup.ItemId))
            {
                METItemStatus orgItemStatus = metInventItemOrderSetup.ItemStatus;

                ttsbegin;
                update_recordset metInventItemOrderSetupToDiscontinue
                setting ItemStatus = METConstants::Discontinued
                where metInventItemOrderSetupToDiscontinue.ItemId == metInventItemOrderSetup.ItemId
                    && metInventItemOrderSetupToDiscontinue.SiteId == metInventItemOrderSetup.SiteId
                    && (metInventItemOrderSetupToDiscontinue.ItemStatus != METConstants::Discontinued && metInventItemOrderSetupToDiscontinue.ItemStatus != METConstants::Deleted)
                    && (metInventItemOrderSetupToDiscontinue.DiscontinueDate != Global::DateNull()
                    && metInventItemOrderSetupToDiscontinue.DiscontinueDate <= DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));

                // New condition to make Item as Actice from discontinue batch job
                update_recordset metInventItemOrderSetupToActive
                setting ItemStatus = METConstants::Active
                where metInventItemOrderSetupToActive.ItemId == metInventItemOrderSetup.ItemId
                    && metInventItemOrderSetupToActive.SiteId == metInventItemOrderSetup.SiteId
                    && metInventItemOrderSetupToActive.ItemStatus == METConstants::Discontinued
                    && (metInventItemOrderSetupToActive.DiscontinueDate == Global::DateNull()
                    || metInventItemOrderSetupToActive.DiscontinueDate > DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
                ttscommit;

                metInventItemOrderSetup.reread();

                //NS-Bug 218466: CB267 - Change Item Status batch job = Discontinued not working when the Discontinue Date field is updated to a future date or removed
                ttsbegin;
                if (metInventItemOrderSetup.ItemStatus == METConstants::Discontinued ||
                    substitutionChildItemSet.in(strFmt("%1|%2", metInventItemOrderSetup.ItemId, metInventItemOrderSetup.SiteId)) ||
                    metInventItemOrderSetup.DistributionMethod == 'H')
                {
                    // By default, when the item status changes: Discontinued: Purchase stopped = Yes
                    // If the item is a Child item, Purchase stopped must be Yes
                    // If the item is a Direct item (Item distribution method = H), Purchase stopped must be Yes
                    update_recordset inventItemPurchSetup setting Override = NoYes::Yes, Stopped = NoYes::Yes
                    where inventItemPurchSetup.ItemId == metInventItemOrderSetup.ItemId
                    && inventItemPurchSetup.InventDimId == metInventItemOrderSetup.InventDimId
                    && inventItemPurchSetup.Stopped != NoYes::Yes;
                }
                else if (metInventItemOrderSetup.ItemStatus == METConstants::Active && orgItemStatus == METConstants::Discontinued)
                {
                    //By default, when the item status changes: Active: Purchase stopped = No
                    update_recordset inventItemPurchSetup setting Override = NoYes::Yes, Stopped = NoYes::No
                    where inventItemPurchSetup.ItemId == metInventItemOrderSetup.ItemId
                    && inventItemPurchSetup.InventDimId == metInventItemOrderSetup.InventDimId 
                    && inventItemPurchSetup.Stopped != NoYes::No;
                }
                ttscommit;
                //NE-Bug 218466: CB267 - Change Item Status batch job = Discontinued not working when the Discontinue Date field is updated to a future date or removed
            }
        }
    }

    /// <summary>
    /// This method will get the child item which are linked to parent item through item substitution.
    /// </summary>
    /// <returns>Set</returns>
    private set getSubstitutionChildItemSet()
    {
        Set ret  = new Set(Types::String);
        METSalesItemSubstitutionParentChild metSalesItemSubstitutionParentChild;

        while select ChildItemID, InventSiteId from metSalesItemSubstitutionParentChild
            group by ChildItemID, InventSiteId
            where metSalesItemSubstitutionParentChild.ChildItemID && metSalesItemSubstitutionParentChild.InventSiteId
            
        {
            ret.add(strFmt("%1|%2", metSalesItemSubstitutionParentChild.ChildItemID, metSalesItemSubstitutionParentChild.InventSiteId));
        }

        return ret;
    }

    /// <summary>
    /// This method checks if Item is Child or not
    /// </summary>
    /// <param name = "_itemId">Item Id</param>
    /// <param name = "_inventSiteId">Site Id</param>
    /// <returns>boolean</returns>
    private boolean checkIfItemIsChild(ItemId _itemId, InventSiteId _inventSiteId)
    {
        METSalesItemSubstitutionParentChild metSalesItemSubstitutionParentChild;

        select firstonly RecId
            from metSalesItemSubstitutionParentChild
            where metSalesItemSubstitutionParentChild.ChildItemID == _itemId
            && metSalesItemSubstitutionParentChild.InventSiteId == _inventSiteId;
        
        if (metSalesItemSubstitutionParentChild.RecId)
        {
            return true;
        }

        return false;
    }

    private boolean checkIfItemIsTemp(ItemId _itemId)
    {
        EcoResProductAttributeValueV3Entity  ecoResProductAttributeValueV3Entity;
        boolean                     res;

        if (! tempItemForPackChangeSet)
        {
            tempItemForPackChangeSet = new Set(Types::String);

            while select PRODUCTNUMBER from ecoResProductAttributeValueV3Entity
                where ecoResProductAttributeValueV3Entity.AttributeName == METConstants::TempItemForPackChange
                   && ecoResProductAttributeValueV3Entity.BOOLEANVALUE  == 1
            {
                tempItemForPackChangeSet.add(ecoResProductAttributeValueV3Entity.PRODUCTNUMBER);
            }
        }
        res = tempItemForPackChangeSet.in(_itemId);

        return res;

    }

    private boolean checkIfItemIsTempItemForPackChange(ItemId _itemId)
    {
        METInventItemOrderSetup inventItemOrderSetup;

        select firstonly RecId
            from inventItemOrderSetup
            where inventItemOrderSetup.TempItemPackChg == _itemId;

        if (inventItemOrderSetup)
        {
            return true;
        }

        return false;
    }

    /// <summary>
    /// to change the item site level field called Item status to 'Active'.
    /// MPJ_22974_BMSProductMDRItemStatusAndPackChange
    /// </summary>
    /// <param name = "_queryRun"> query to select rcords </param>
    private void changeStatusToActive(QueryRun _queryRun)
    {
        
        while(_queryRun.next())
        {
            METInventItemOrderSetup    metInventItemOrderSetup, metInventItemOrderSetupSupplySite;
            metInventItemOrderSetup = _queryRun.get(tableNum(METInventItemOrderSetup));
            
            if (!this.checkIfItemIsChild(metInventItemOrderSetup.ItemId, metInventItemOrderSetup.SiteId) && this.continueForItem(metInventItemOrderSetup.ItemId))
            {
                METReqItemTableInventDimView metReqItemTableInventDimView;
                METItemStatusWarehouses metItemStatusWarehouses;
                
                while select ItemId, CovInventDimId, ReqPOType, InventLocationIdReqMain, VendId, MainWarehouseInventSiteId
                    from metReqItemTableInventDimView
                    where metReqItemTableInventDimView.ItemId == metInventItemOrderSetup.ItemId
                    && metReqItemTableInventDimView.InventSiteId == metInventItemOrderSetup.SiteId
                    && metReqItemTableInventDimView.ReqPOType == ReqPOType::Transfer
                    && metReqItemTableInventDimView.MainWarehouseInventSiteId != ''
                    && metReqItemTableInventDimView.MainWarehouseInventSiteId != metInventItemOrderSetup.SiteId
                    notexists join metItemStatusWarehouses
                    where metItemStatusWarehouses.InventLocationId == metReqItemTableInventDimView.InventLocationId
                {
                    select firstonly RecId
                        from metInventItemOrderSetupSupplySite
                        where metInventItemOrderSetupSupplySite.ItemId  == metInventItemOrderSetup.ItemId
                        && metInventItemOrderSetupSupplySite.SiteId   == metReqItemTableInventDimView.MainWarehouseInventSiteId
                        && metInventItemOrderSetupSupplySite.ItemStatus ==  METConstants::Active;
                        
                    if (metInventItemOrderSetupSupplySite)
                    {
                        this.updateStatusToActive(metInventItemOrderSetup);
                        METInventItemOrderSetup::updateChildItemSiteStatus(metInventItemOrderSetup.ItemId, metInventItemOrderSetup.SiteId);

                        //Activate all transfer sites
                        METChangeItemStatusHelper metChangeItemStatusHelper = new METChangeItemStatusHelper();
                        metChangeItemStatusHelper.updateItemStatusOfTransferSite(metInventItemOrderSetup.ItemId, metInventItemOrderSetup.SiteId, METItemStatusTable::findByStatus(METItemsStatus::Active).ItemStatus);
                    }
                    
                }
                while select ItemId, CovInventDimId, ReqPOType, InventLocationIdReqMain, VendId, VendIntercompanyWarehouse
                    from metReqItemTableInventDimView
                    where metReqItemTableInventDimView.ItemId == metInventItemOrderSetup.ItemId
                    && metReqItemTableInventDimView.InventSiteId == metInventItemOrderSetup.SiteId
                    && metReqItemTableInventDimView.ReqPOType == ReqPOType::Purch
                    && metReqItemTableInventDimView.METInterCompanySourced == NoYes::Yes
                    notexists join metItemStatusWarehouses
                    where metItemStatusWarehouses.InventLocationId == metReqItemTableInventDimView.InventLocationId
                {
                    boolean updateToActive;
                    
                    InventLocationId interCompInventLocationId = metReqItemTableInventDimView.VendIntercompanyWarehouse;

                    if (interCompInventLocationId)
                    {
                        changecompany(inventParameters.METInterCompanyPurchaseLegalEntity)
                        {
                            InventLocation inventLocationIntCom;

                            select firstonly InventSiteId from inventLocationIntCom
                            where inventLocationIntCom.InventLocationId == interCompInventLocationId;

                            if (inventLocationIntCom)
                            {
                                METInventItemOrderSetup     metInventItemOrderSetupIntCom;

                                select firstonly RecId
                                from metInventItemOrderSetupIntCom
                                where metInventItemOrderSetupIntCom.ItemId == metInventItemOrderSetup.ItemId
                                    && metInventItemOrderSetupIntCom.SiteId == inventLocationIntCom.InventSiteId
                                    && metInventItemOrderSetupIntCom.ItemStatus ==  METConstants::Active;

                                if(metInventItemOrderSetupIntCom)
                                {
                                    updateToActive = true;
                                }
                            }
                        }
                        //Update Active status in current batch job
                        if (updateToActive)
                        {
                            this.updateStatusToActive(metInventItemOrderSetup);
                            METInventItemOrderSetup::updateChildItemSiteStatus(metInventItemOrderSetup.ItemId, metInventItemOrderSetup.SiteId);

                            //Activate all transfer sites
                            METChangeItemStatusHelper metChangeItemStatusHelper = new METChangeItemStatusHelper();
                            metChangeItemStatusHelper.updateItemStatusOfTransferSite(metInventItemOrderSetup.ItemId, metInventItemOrderSetup.SiteId, METItemStatusTable::findByStatus(METItemsStatus::Active).ItemStatus);
                        }
                    }
                }
                //Intercompany in other legal entity
                
                if (inventParameters.METInterCompanyPurchaseLegalEntity)
                {
                    Set setWarehouse = new Set(Types::String);

                    while select InventSiteId, InventLocationId from metReqItemTableInventDimView
                        where metReqItemTableInventDimView.ItemId == metInventItemOrderSetup.ItemId
                        && metReqItemTableInventDimView.InventSiteId == metInventItemOrderSetup.SiteId
                    {
                        if (InventLocation::find(metReqItemTableInventDimView.InventLocationId).METNDCWarehouse)
                        {
                            InventLocation inventLocation;

                            while select InventLocationId from inventLocation
                                where inventLocation.METNDCWarehouse == NoYes::Yes
                            {
                                if (!setWarehouse.in(inventLocation.InventLocationId))
                                {
                                    setWarehouse.add(inventLocation.InventLocationId);
                                }
                            }
                        }
                        else
                        {
                            if (!setWarehouse.in(metReqItemTableInventDimView.InventLocationId))
                            {
                                setWarehouse.add(metReqItemTableInventDimView.InventLocationId);
                            }
                        }
                    }

                    changecompany(inventParameters.METInterCompanyPurchaseLegalEntity)
                    {
                        METReqItemTableInventDimView metReqItemTableInventDimViewIntCom;
                        METItemStatusWarehouses metItemStatusWarehousesIntCom;

                        while select InventSiteId, InventLocationId, VendIntercompanyWarehouse from metReqItemTableInventDimViewIntCom
                            where metReqItemTableInventDimViewIntCom.ItemId == metInventItemOrderSetup.ItemId
                            && metReqItemTableInventDimViewIntCom.ReqPOType == ReqPOType::Purch
                            && metReqItemTableInventDimViewIntCom.METInterCompanySourced == NoYes::Yes
                            notexists join metItemStatusWarehousesIntCom
                            where metItemStatusWarehousesIntCom.InventLocationId == metReqItemTableInventDimViewIntCom.InventLocationId
                        {
                            if (setWarehouse.in(metReqItemTableInventDimViewIntCom.VendIntercompanyWarehouse))
                            {
                                this.updateStatusToActive(METInventItemOrderSetup::findByItemAndSite(metInventItemOrderSetup.ItemId, metReqItemTableInventDimViewIntCom.InventSiteId, true));
                                METInventItemOrderSetup::updateChildItemSiteStatus(metInventItemOrderSetup.ItemId, metReqItemTableInventDimViewIntCom.InventSiteId);

                                //Activate all transfer sites
                                METChangeItemStatusHelper metChangeItemStatusHelperIntCom = new METChangeItemStatusHelper();
                                metChangeItemStatusHelperIntCom.updateItemStatusOfTransferSite(metInventItemOrderSetup.ItemId, metReqItemTableInventDimViewIntCom.InventSiteId, METItemStatusTable::findByStatus(METItemsStatus::Active).ItemStatus);
                            }
                        }
                    }
                }
            }
        }
    }

/// <summary>
/// Update Status method
/// </summary>
/// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup</param>
/// <param name = "_status">METItemStatus</param>
public void updateStatus(METInventItemOrderSetup _metInventItemOrderSetup, METItemStatus _status)
{
    if (_metInventItemOrderSetup)
    {
        ttsbegin;
        _metInventItemOrderSetup.selectForUpdate(true);
        _metInventItemOrderSetup.ItemStatus = _status;
        if (_metInventItemOrderSetup.orig().ItemStatus != _metInventItemOrderSetup.ItemStatus)
        {   
            _metInventItemOrderSetup.update();
        }
        ttscommit;
    }
}

    /// <summary>
    /// Update status to Active
    /// </summary>
    /// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup</param>
    public void updateStatusToActive(METInventItemOrderSetup _metInventItemOrderSetup)
    {
        if (_metInventItemOrderSetup)
        {
            ttsbegin;
            _metInventItemOrderSetup.selectForUpdate(true);
            _metInventItemOrderSetup.ItemStatus = METItemStatusTable::findByStatus(METItemsStatus::Active).ItemStatus;
            _metInventItemOrderSetup.PublishPriceBook = NoYes::Yes;
            _metInventItemOrderSetup.PublishPortal = NoYes::Yes;
            _metInventItemOrderSetup.PublishHost = NoYes::Yes;

            if (_metInventItemOrderSetup.orig().ItemStatus       != _metInventItemOrderSetup.ItemStatus ||
                _metInventItemOrderSetup.orig().PublishPriceBook != _metInventItemOrderSetup.PublishPriceBook ||
                _metInventItemOrderSetup.orig().PublishPortal    != _metInventItemOrderSetup.PublishPortal ||
                _metInventItemOrderSetup.orig().PublishHost      != _metInventItemOrderSetup.PublishHost)
            {
                _metInventItemOrderSetup.update();
            }
            ttscommit;
        }
    }

    /// <summary>
    /// Update status to New
    /// </summary>
    /// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup</param>
    public void updateStatusToNew(METInventItemOrderSetup _metInventItemOrderSetup)
    {
        if (_metInventItemOrderSetup)
        {
            ttsbegin;
            _metInventItemOrderSetup.selectForUpdate(true);
            _metInventItemOrderSetup.ItemStatus = METItemStatusTable::findByStatus(METItemsStatus::New).ItemStatus;
            _metInventItemOrderSetup.PublishPriceBook = NoYes::No;
            _metInventItemOrderSetup.PublishPortal = NoYes::No;
            _metInventItemOrderSetup.PublishHost = NoYes::No;

            if (_metInventItemOrderSetup.orig().ItemStatus       != _metInventItemOrderSetup.ItemStatus ||
                _metInventItemOrderSetup.orig().PublishPriceBook != _metInventItemOrderSetup.PublishPriceBook ||
                _metInventItemOrderSetup.orig().PublishPortal    != _metInventItemOrderSetup.PublishPortal ||
                _metInventItemOrderSetup.orig().PublishHost      != _metInventItemOrderSetup.PublishHost)
            {
                _metInventItemOrderSetup.update();
            }
            ttscommit;
        }
    }

    /// <summary>
    /// Validate NDC site
    /// </summary>
    /// <param name = "_ndcWarehouseMap">Pre-loaded NDC warehouse map (key: InventLocationId, value: InventSiteId)</param>
    /// <param name = "_metReqItemTableInventDimView">Planned order view row (pre-fetched by caller)</param>
    /// <param name = "_itemId">ItemId</param>
    /// <returns>boolean</returns>
    private boolean changeStatusToDeleted_ValidateNDC(Map _ndcWarehouseMap, METReqItemTableInventDimView _metReqItemTableInventDimView, ItemId _itemId)
    {
        boolean ret = true;
        // Fetch METReqItemTable once — shared across all per-warehouse Validate calls below.
        METReqItemTable metReqItemTable    = METReqItemTable::find(_metReqItemTableInventDimView.ReqItemTableRecId);
        MapEnumerator   ndcWarehouseMapEnumerator = _ndcWarehouseMap.getEnumerator();

        while (ndcWarehouseMapEnumerator.moveNext())
        {
            ret = this.changeStatusToDeleted_Validate(ndcWarehouseMapEnumerator.currentValue(), ndcWarehouseMapEnumerator.currentKey(), _metReqItemTableInventDimView, _itemId);

            if (!ret)
            {
                return ret;
            }
        }

        return ret;
    }

    /// <summary>
    /// Change status to NEW
    /// </summary>
    /// <param name = "_queryRun">QueryRun</param>
    private void changeStatusToNew(QueryRun _queryRun)
    {
        
        while(_queryRun.next())
        {
            METInventItemOrderSetup    metInventItemOrderSetup, metInventItemOrderSetupSupplySite;
            metInventItemOrderSetup = _queryRun.get(tableNum(METInventItemOrderSetup));
            
            if (!this.checkIfItemIsChild(metInventItemOrderSetup.ItemId, metInventItemOrderSetup.SiteId) && this.continueForItem(metInventItemOrderSetup.ItemId))
            {
                METReqItemTableInventDimView metReqItemTableInventDimView;
                METItemStatusWarehouses metItemStatusWarehouses;
                
                while select ItemId, CovInventDimId, ReqPOType, InventLocationIdReqMain, VendId, MainWarehouseInventSiteId
                    from metReqItemTableInventDimView
                    where metReqItemTableInventDimView.ItemId == metInventItemOrderSetup.ItemId
                    && metReqItemTableInventDimView.InventSiteId == metInventItemOrderSetup.SiteId
                    && metReqItemTableInventDimView.ReqPOType == ReqPOType::Transfer
                    && metReqItemTableInventDimView.MainWarehouseInventSiteId != ''
                    && metReqItemTableInventDimView.MainWarehouseInventSiteId != metInventItemOrderSetup.SiteId
                    notexists join metItemStatusWarehouses
                    where metItemStatusWarehouses.InventLocationId == metReqItemTableInventDimView.InventLocationId
                {
                    select firstonly RecId
                        from metInventItemOrderSetupSupplySite
                        where metInventItemOrderSetupSupplySite.ItemId  == metInventItemOrderSetup.ItemId
                        && metInventItemOrderSetupSupplySite.SiteId   == metReqItemTableInventDimView.MainWarehouseInventSiteId
                        && metInventItemOrderSetupSupplySite.ItemStatus ==  METConstants::NewStr;
                        
                    if (metInventItemOrderSetupSupplySite)
                    {
                        this.updateStatusToNew(metInventItemOrderSetup);
                        METInventItemOrderSetup::updateChildItemSiteStatus(metInventItemOrderSetup.ItemId, metInventItemOrderSetup.SiteId);

                        //Update to all transfer sites
                        METChangeItemStatusHelper metChangeItemStatusHelper = new METChangeItemStatusHelper();
                        metChangeItemStatusHelper.updateItemStatusOfTransferSite(metInventItemOrderSetup.ItemId, metInventItemOrderSetup.SiteId, METItemStatusTable::findByStatus(METItemsStatus::New).ItemStatus);
                    }
                    
                }
                while select ItemId, CovInventDimId, ReqPOType, InventLocationIdReqMain, VendId, VendIntercompanyWarehouse
                    from metReqItemTableInventDimView
                    where metReqItemTableInventDimView.ItemId == metInventItemOrderSetup.ItemId
                    && metReqItemTableInventDimView.InventSiteId == metInventItemOrderSetup.SiteId
                    && metReqItemTableInventDimView.ReqPOType == ReqPOType::Purch
                    && metReqItemTableInventDimView.METInterCompanySourced == NoYes::Yes
                    notexists join metItemStatusWarehouses
                    where metItemStatusWarehouses.InventLocationId == metReqItemTableInventDimView.InventLocationId
                {
                    boolean updateToNew;
                    
                    InventLocationId interCompInventLocationId = metReqItemTableInventDimView.VendIntercompanyWarehouse;

                    if (interCompInventLocationId)
                    {
                        changecompany(inventParameters.METInterCompanyPurchaseLegalEntity)
                        {
                            InventLocation inventLocationIntCom;

                            select firstonly InventSiteId from inventLocationIntCom
                            where inventLocationIntCom.InventLocationId == interCompInventLocationId;

                            if (inventLocationIntCom)
                            {
                                METInventItemOrderSetup     metInventItemOrderSetupIntCom;

                                select firstonly RecId
                                from metInventItemOrderSetupIntCom
                                where metInventItemOrderSetupIntCom.ItemId == metInventItemOrderSetup.ItemId
                                    && metInventItemOrderSetupIntCom.SiteId == inventLocationIntCom.InventSiteId
                                    && metInventItemOrderSetupIntCom.ItemStatus ==  METConstants::NewStr;

                                if(metInventItemOrderSetupIntCom)
                                {
                                    updateToNew = true;
                                }
                            }
                        }
                        //Update New status in current batch job
                        if (updateToNew)
                        {
                            this.updateStatusToNew(metInventItemOrderSetup);
                            METInventItemOrderSetup::updateChildItemSiteStatus(metInventItemOrderSetup.ItemId, metInventItemOrderSetup.SiteId);

                            //Update to all transfer sites
                            METChangeItemStatusHelper metChangeItemStatusHelper = new METChangeItemStatusHelper();
                            metChangeItemStatusHelper.updateItemStatusOfTransferSite(metInventItemOrderSetup.ItemId, metInventItemOrderSetup.SiteId, METItemStatusTable::findByStatus(METItemsStatus::New).ItemStatus);
                        }
                    }
                }

                //Intercompany in other legal entity
                
                if (inventParameters.METInterCompanyPurchaseLegalEntity)
                {
                    Set setWarehouse = new Set(Types::String);

                    while select InventSiteId, InventLocationId from metReqItemTableInventDimView
                        where metReqItemTableInventDimView.ItemId == metInventItemOrderSetup.ItemId
                        && metReqItemTableInventDimView.InventSiteId == metInventItemOrderSetup.SiteId
                    {
                        if (InventLocation::find(metReqItemTableInventDimView.InventLocationId).METNDCWarehouse)
                        {
                            InventLocation inventLocation;

                            while select InventLocationId from inventLocation
                                where inventLocation.METNDCWarehouse == NoYes::Yes
                            {
                                if (!setWarehouse.in(inventLocation.InventLocationId))
                                {
                                    setWarehouse.add(inventLocation.InventLocationId);
                                }
                            }
                        }
                        else
                        {
                            if (!setWarehouse.in(metReqItemTableInventDimView.InventLocationId))
                            {
                                setWarehouse.add(metReqItemTableInventDimView.InventLocationId);
                            }
                        }
                    }

                    changecompany(inventParameters.METInterCompanyPurchaseLegalEntity)
                    {
                        METReqItemTableInventDimView metReqItemTableInventDimViewIntCom;
                        METItemStatusWarehouses metItemStatusWarehousesIntCom;

                        while select InventSiteId, InventLocationId, VendIntercompanyWarehouse from metReqItemTableInventDimViewIntCom
                            where metReqItemTableInventDimViewIntCom.ItemId == metInventItemOrderSetup.ItemId
                            && metReqItemTableInventDimViewIntCom.ReqPOType == ReqPOType::Purch
                            && metReqItemTableInventDimViewIntCom.METInterCompanySourced == NoYes::Yes
                            notexists join metItemStatusWarehousesIntCom
                            where metItemStatusWarehousesIntCom.InventLocationId == metReqItemTableInventDimViewIntCom.InventLocationId
                        {
                            if (setWarehouse.in(metReqItemTableInventDimViewIntCom.VendIntercompanyWarehouse))
                            {
                                this.updateStatusToNew(METInventItemOrderSetup::findByItemAndSite(metInventItemOrderSetup.ItemId, metReqItemTableInventDimViewIntCom.InventSiteId, true));
                                METInventItemOrderSetup::updateChildItemSiteStatus(metInventItemOrderSetup.ItemId, metReqItemTableInventDimViewIntCom.InventSiteId);

                                //update new to all transfer sites
                                METChangeItemStatusHelper metChangeItemStatusHelperIntCom = new METChangeItemStatusHelper();
                                metChangeItemStatusHelperIntCom.updateItemStatusOfTransferSite(metInventItemOrderSetup.ItemId, metReqItemTableInventDimViewIntCom.InventSiteId, METItemStatusTable::findByStatus(METItemsStatus::New).ItemStatus);
                            }
                        }
                    }
                }
            }
        }
    }

    /// <summary>
    /// Copy reason code, vend replacement and update to Deleted status for main item and child items
    /// </summary>
    /// <param name = "_metInventItemOrderSetupSource">METInventItemOrderSetup</param>
    /// <param name = "_metInventItemOrderSetupDestination">METInventItemOrderSetup</param>
    private void copyDelReasonAFromSourceToTransferSiteAndDeleteMain(METInventItemOrderSetup _metInventItemOrderSetupSource, METInventItemOrderSetup _metInventItemOrderSetupDestination)
    {
        if (_metInventItemOrderSetupDestination)
        {
            this.copyDelReasonAFromSourceToTransferSiteAndDelete(_metInventItemOrderSetupSource,_metInventItemOrderSetupDestination);

            METSalesItemSubstitutionParentChild childItems;
            METInventItemOrderSetup metInventItemOrderSetupForChildItems;
                                                        
            while select ChildItemID, InventSiteId from childItems
                join forupdate metInventItemOrderSetupForChildItems
                where childItems.ParentItemID == _metInventItemOrderSetupDestination.ItemId
                && childItems.InventSiteId == _metInventItemOrderSetupDestination.SiteId
                && metInventItemOrderSetupForChildItems.ItemId == childItems.ChildItemID
                && metInventItemOrderSetupForChildItems.SiteId == childItems.InventSiteId
            {
                this.copyDelReasonAFromSourceToTransferSiteAndDelete(_metInventItemOrderSetupDestination,metInventItemOrderSetupForChildItems);
            }
        }
    }

    /// <summary>
    /// Copy deletion reason and Vend replacement and make status as Deleted
    /// </summary>
    /// <param name = "_metInventItemOrderSetupSource">METInventItemOrderSetup</param>
    /// <param name = "_metInventItemOrderSetupDestination">METInventItemOrderSetup</param>
    private void copyDelReasonAFromSourceToTransferSiteAndDelete(METInventItemOrderSetup _metInventItemOrderSetupSource, METInventItemOrderSetup _metInventItemOrderSetupDestination)
    {
        if (_metInventItemOrderSetupDestination)
        {
            ttsbegin;
            _metInventItemOrderSetupDestination.selectForUpdate(true);
            _metInventItemOrderSetupDestination.ItemStatus      = METConstants::Deleted;
            _metInventItemOrderSetupDestination.DiscontinueDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
            _metInventItemOrderSetupDestination.VendReplacement = _metInventItemOrderSetupSource.VendReplacement;
            _metInventItemOrderSetupDestination.DeletionReason  = _metInventItemOrderSetupSource.DeletionReason;
            _metInventItemOrderSetupDestination.DeleteStatusDate    = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
            _metInventItemOrderSetupDestination.SubrangeId          = '';
            _metInventItemOrderSetupDestination.SubrangeDesc        = '';
            _metInventItemOrderSetupDestination.update();

            InventItemPurchSetup inventItemPurchSetup = InventItemPurchSetup::find(_metInventItemOrderSetupDestination.ItemId, _metInventItemOrderSetupDestination.InventDimId, true);

            if (inventItemPurchSetup)
            {
                inventItemPurchSetup.Override = true;
                inventItemPurchSetup.Stopped  = true;
                inventItemPurchSetup.update();
            }
            ttscommit;
        }

    }
